ub.com/nodejs/node/commit/f7406aa56d\",\"label\":\"f7406aa56d\"},{\"url\":\"https://github.com/nodejs/node/commit/c7493fac5e\",\"label\":\"c7493fac5e\"},{\"url\":\"https://github.com/nodejs/node/commit/50a8527867\",\"label\":\"50a8527867\"},{\"url\":\"https://github.com/nodejs/node/commit/9c1ebb713c\",\"label\":\"9c1ebb713c\"},{\"url\":\"https://github.com/nodejs/node/commit/fb3d5ea45d\",\"label\":\"fb3d5ea45d\"},{\"url\":\"https://github.com/nodejs/node/commit/756abacf73\",\"label\":\"756abacf73\"},{\"url\":\"https://github.com/nodejs/node/commit/f8953e54b0\",\"label\":\"f8953e54b0\"},{\"url\":\"https://github.com/nodejs/node/commit/c8a0e205e1\",\"label\":\"c8a0e205e1\"},{\"url\":\"https://github.com/nodejs/node/commit/1689ee84ce\",\"label\":\"1689ee84ce\"},{\"url\":\"https://github.com/nodejs/node/commit/15f2fb9467\",\"label\":\"15f2fb9467\"},{\"url\":\"https://github.com/nodejs/node/commit/4ab254c9f2\",\"label\":\"4ab254c9f2\"}],\"outline\":\"Node.js 24.0.0 (Current)\\n2025-05-06, Version 24.0.0 (Current), @RafaelGSS and @juanarbol\\nNotable Changes\\nV8 13.6\\nnpm 11\\nAsyncLocalStorage defaults to AsyncContextFrame\\nURLPattern as a global\\nPermission Model Improvements\\nTest Runner Enhancements\\nUndici 7\\nDeprecations and Removals\\nSemver-Major Commits\\nSemver-Minor Commits\\nSemver-Patch Commits\\nSHASUMS\",\"segmentIndex\":0,\"segmentCount\":5,\"truncated\":true,\"captureTruncated\":false,\"httpStatus\":200}"
